# spinel: not-cruby -- OpenSSL::PKey::RSA.from_public_components has no CRuby spelling; the expected answers are CRuby's verify / verify_pss on the same key built from DER
require "openssl"

n = [""].pack("H*")
e = ["010001"].pack("H*")
data = ["61757468656e74696361746f722064617461207c7c20636c69656e7420646174612068617368200001"].pack("H*")
pk1 = [""].pack("H*")
pss = [""].pack("H*")
pss32 = [""].pack("H*")
key = OpenSSL::PKey::RSA.from_public_components(n, e)
p key.verify("SHA256", pk1, data)
p key.verify("SHA256", pk1, data + "x")
p key.verify_pss("SHA256", pss, data, salt_length: :auto, mgf1_hash: "SHA256")
p key.verify_pss("SHA256", pss32, data, salt_length: :auto, mgf1_hash: "SHA256")
p key.verify_pss("SHA256", pss, data + "x", salt_length: :auto, mgf1_hash: "SHA256")
p key.verify("SHA256", pss, data)
